function buildModel(replicad, params) {
  const { drawCircle, drawRectangle } = replicad;

  // Flange
  let flange = drawCircle(params.flangeRadius).sketchOnPlane().extrude(params.flangeThickness);

  // Bolt Holes
  const holeRadius = params.boltHoleRadius;
  const holeInset = params.holeInset;
  const flangeCenter = [0, 0];
  const positions = [
    [holeInset, holeInset],
    [-holeInset, holeInset],
    [holeInset, -holeInset],
    [-holeInset, -holeInset]
  ];

  for (const [x, y] of positions) {
    const hole = drawCircle(holeRadius).translate([x, y]).sketchOnPlane().extrude(params.flangeThickness);
    flange = flange.cut(hole);
  }

  // Tube
  const tube = drawCircle(params.tubeRadius).sketchOnPlane('XY', params.flangeThickness).extrude(params.tubeHeight);
  flange = flange.fuse(tube);

  // Bore
  const bore = drawCircle(params.boreRadius).sketchOnPlane().extrude(params.flangeThickness + params.tubeHeight);
  flange = flange.cut(bore);

  return flange;
}
